                "skills": [
                  {
                    "id": "9702_skill_errors_uncertainties",
                    "name": "Errors and Uncertainties",
                    "description": "Combine measurement uncertainties and evaluate systematic vs random errors."
                  }
                ],
                "definitions": [
                  {
                    "id": "9702_def_instrument_resolution",
                    "term": "instrument resolution",
                    "description": "the smallest change in a quantity that a measuring instrument can distinguish, usually set by its smallest scale division"
                  },
                  {
                    "id": "9702_def_accuracy",
                    "term": "accuracy",
                    "description": "the closeness of a measured value to the true value of the quantity"
                  }
                ],
                "formulas": [],
                "hints": [
                  "Separate how finely the micrometer can resolve the wire diameter from how close its measured diameter is to the true value.",
                  "For this micrometer, precision can be described by its 0.01 mm smallest division; accuracy concerns closeness to the true diameter."
                ],
                "walkthrough": [
                  "Precision here is the resolution of the measuring instrument: the smallest division of the micrometer is 0.01 mm, so it can distinguish diameter changes at that scale.",
                  "Accuracy is how close the measured diameter is to the true diameter of the wire.",
                  "Thus a micrometer may give readings to 0.01 mm without necessarily being accurate if, for example, a zero error shifts every reading away from the true diameter."
                ],
                "criteria": [
                  {
                    "id": "9702_s16_23_q02_b_mp01",
                    "occurrence": null,
                    "alternatives": [],
                    "official": "precision: the size of the smallest division (on the measuring instrument) or 0.01 mm for the micrometer",
                    "observable": "States that precision is set by the micrometer's smallest division or gives its 0.01 mm resolution."
                  },
                  {
                    "id": "9702_s16_23_q02_b_mp02",
                    "occurrence": null,
                    "alternatives": [],
                    "official": "accuracy: how close (diameter) value is to the true (diameter) value",
                    "observable": "States that accuracy is the closeness of the measured diameter to the true diameter."
                  }
                ],
